import { colors, Theme, useTheme } from '@/theme'
import {
	View,
	Text,
	TouchableOpacity,
	ViewStyle,
	TextStyle,
	LayoutChangeEvent
} from 'react-native'
import { Check, Mic, X } from 'lucide-react-native'
import { defineStyles } from '@/utils/defineStyles'
import { ReactNode, useState } from 'react'
import { ShineEffect } from '@/components/primitives/ShineEffect'
import * as Haptics from 'expo-haptics'

type SpeechToTextActionsProps = {
	recognizing: boolean
	isNotEmpty: boolean
	isTransferred: boolean
	handlePause: () => void
	handleStart: () => void
	handleReset: () => void
	handleSubmit: () => void
}

type SpeechToTextTextState = 'Listening' | 'Thinking' | 'Muted'
type SpeechToTextButtonState = 'neutral' | 'muted' | 'stop' | 'submit'

export const SpeechToTextActions = ({
	recognizing,
	isNotEmpty,
	isTransferred,
	handleReset,
	handlePause,
	handleStart,
	handleSubmit
}: SpeechToTextActionsProps) => {
	const { theme, isDark } = useTheme()
	const [shineWidth, setShineWidth] = useState(0)

	const getCurrentStateText = (): SpeechToTextTextState => {
		if (recognizing) {
			return 'Listening'
		}
		if (isTransferred) {
			return 'Thinking'
		}
		return 'Muted'
	}

	const getCurrentStateButton = (): SpeechToTextButtonState => {
		if (recognizing) {
			if (isNotEmpty) {
				return 'submit'
			}
			return 'neutral'
		}
		if (!isNotEmpty) {
			return 'muted'
		}
		return 'stop'
	}

	const buttonConfig = () => {
		const currentStateButton = getCurrentStateButton()

		const config = {
			neutral: {
				icon: <Mic size={24} color={colors[theme].gray[900]} />,
				backgroundColor: { backgroundColor: `${colors[theme].gray[50]}66` },
				onPress: handleStart,
				textColor: { color: `${colors[theme].gray[900]}80` }
			},
			muted: {
				icon: <Mic size={24} color={colors[theme].red[600]} />,
				backgroundColor: { backgroundColor: `${colors[theme].red[50]}66` },
				onPress: handlePause,
				textColor: { color: colors[theme].red[600] }
			},
			stop: {
				icon: <View style={styles.stopButton(theme)} />,
				backgroundColor: { backgroundColor: `${colors[theme].gray[50]}66` },
				onPress: handleReset,
				textColor: { color: `${colors[theme].gray[900]}80` }
			},
			submit: {
				icon: <Check size={24} color={colors[theme].gray[900]} />,
				backgroundColor: {
					backgroundColor: isDark
						? colors[theme].blue[300]
						: colors[theme].blue[50]
				},
				onPress: handleSubmit,
				textColor: { color: `${colors[theme].gray[900]}80` }
			}
		}

		return config[currentStateButton]
	}

	const getCurrentStateButtonIcon = (): ReactNode => {
		return buttonConfig().icon
	}

	const getCurrentStateButtonColor = (): ViewStyle => {
		return buttonConfig().backgroundColor
	}

	const getCurrentStateButtonOnPress = (): (() => void) => {
		return buttonConfig().onPress
	}

	const getCurrentStateTextColor = (): TextStyle => {
		return buttonConfig().textColor
	}

	const handleLayout = (event: LayoutChangeEvent) => {
		const { width } = event.nativeEvent.layout
		setShineWidth(width)
	}

	return (
		<View style={styles.controlsContainer}>
			<TouchableOpacity
				style={styles.resetButton(theme)}
				onPress={() => {
					Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
					handleReset()
				}}
			>
				<X size={24} color={colors[theme].gray[900]} />
			</TouchableOpacity>
			<View onLayout={handleLayout}>
				{getCurrentStateText() === 'Thinking' && (
					<ShineEffect
						shineCondition={getCurrentStateText() === 'Thinking'}
						shineWidth={shineWidth}
						onAnimationComplete={() => {
							// TODO: show project that was made
						}}
					/>
				)}
				<Text style={[styles.statusText, getCurrentStateTextColor()]}>
					{getCurrentStateText()}
				</Text>
			</View>
			<TouchableOpacity
				style={[styles.micButton(theme), getCurrentStateButtonColor()]}
				onPress={() => {
					Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
					getCurrentStateButtonOnPress()()
				}}
			>
				{getCurrentStateButtonIcon()}
			</TouchableOpacity>
		</View>
	)
}

const styles = defineStyles({
	stopButton: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[900],
		width: 20,
		height: 20,
		borderRadius: 4
	}),
	controlsContainer: {
		flexDirection: 'row',
		justifyContent: 'space-between',
		alignItems: 'center'
	},
	resetButton: (theme: Theme) => ({
		backgroundColor: `${colors[theme].gray[50]}66`,
		padding: 20,
		borderRadius: 28
	}),
	statusText: {
		fontWeight: '500',
		fontSize: 20
	},
	micButton: (theme: Theme) => ({
		backgroundColor: `${colors[theme].gray[50]}66`,
		padding: 20,
		borderRadius: 28
	}),
	shine: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		width: 20,
		height: '100%'
	}
})
